// Types for the dashboard's data. Content health, Health and Agent activity are REAL: they come from
// snapshot.json and snapshot-history.json (generated by `npm run snapshot`). Growth and Cost are
// placeholder pages on mock JSON. Import everything from '@/data', never from a JSON file directly.
//
// Sections: Real pages (shared, Content health, Deploys, Health, Agent activity) · Shared (periods,
// stat tiles, chart series) · Growth (mock) · Agents and Cost (mock)

/** A calendar day as an ISO string, 'YYYY-MM-DD'. */
export type IsoDate = string

// ══ Real pages: shared ═══════════════════════════════════════════════════════

/** One point of a trend: the value a snapshot recorded, and when that snapshot was taken. */
export interface TrendPoint {
  /** When the snapshot was taken, e.g. '2026-11-19T14:44:00-06:00'. */
  takenAt: IsoDateTime
  value: number
}

// ══ Content health (real) ════════════════════════════════════════════════════

export type LanguageState = 'live' | 'started' | 'coming-soon'

/** How much of a course's official A1 word list the course teaches. */
export interface Coverage {
  /** The list's short name, e.g. "FLELex" or "Goethe-Institut". */
  list: string
  /** What part of the list is measured: "core 600" or "full list". Show with `coverageListLabel`. */
  scope: string
  /** Words of that scope the course teaches. */
  taught: number
  /** Words in that scope. */
  total: number
  /** taught / total as a whole percent, 0–100, as the course's own report gives it. */
  percent: number
}

/**
 * One language. A coming-soon language has null in every field after `state`. For a live language a
 * null means the snapshot had no source for that number: show `NOT_MEASURED`, never 0.
 */
export interface RealLanguage {
  /** Stable key, e.g. 'fr'. */
  id: string
  /** Display name, e.g. "French". */
  name: string
  state: LanguageState
  /** Whether every part of the course is live. null for coming-soon. Use `languageStatusKey`. */
  status: 'complete' | 'incomplete' | 'started' | null
  partsLive: number | null
  partsTotal: number | null
  /** Circles on the course tree. */
  circles: number | null
  /** Live sentences. */
  /** The CEFR level the course teaches, e.g. "A1". */
  level: string | null
  /** Words in the course's word list. */
  words: number | null
  sentences: number | null
  /** Of those, sentences from Tatoeba. */
  sentencesTatoeba: number | null
  /** Of those, sentences drafted for the course. */
  sentencesDrafted: number | null
  coverage: Coverage | null
  /** Awaiting native check: drafted sentences live in lessons but not yet checked by a native speaker. */
  draftsWaiting: number | null
  /** The latest deploy that changed this language. `date` is a date-time: use `formatDate`. */
  lastDeploy: { number: number; name: string; date: IsoDateTime } | null
}

// ══ Deploys (real; on the Content health page) ═══════════════════════════════

/** 'not-recorded': no test run exists for this deploy. Its counts are then null. */
export type DeployTestResult = 'passed' | 'failed' | 'running' | 'not-recorded'

export interface RealDeploy {
  /** The deploy number, e.g. 58. Use it as the React key. */
  number: number
  /** The deploy's animal name, e.g. "Dolphin". */
  name: string
  /** When it was deployed. Format with `formatDate` or `formatDateTime`. */
  date: IsoDateTime
  /** Short commit hash. */
  commit: string
  /** What changed, one line each. */
  changes: string[]
  /** How many change lines were left out of `changes`. */
  changesHidden: number
  /** The full test run for this deploy. Show `result` with `deployTestLabels`, counts with `formatDeployTest`. */
  test: { result: DeployTestResult; tests: number | null; passed: number | null; failed: number | null }
}

// ══ Health (real) ════════════════════════════════════════════════════════════

export type HealthCheckResult = 'pass' | 'fail' | 'not-measured'

/** One row of the Health checks table. */
export interface HealthCheck {
  /** 'full-suite' | 'audits' | 'smoke' | 'fast-tier' | 'uptime' | 'response-time'. */
  id: string
  name: string
  /** When it last ran, or null when no run is on record. Format with `formatDateTime`. */
  lastRun: IsoDateTime | null
  /** Show it with `healthCheckResultLabels`. */
  result: HealthCheckResult
  /** One or two plain sentences: the counts, or why there is no measurement. */
  detail: string
}

// ══ Agent activity (real) ════════════════════════════════════════════════════

/** One day of the activity chart. */
export interface ActivityDay {
  date: IsoDate
  commits: number
  /** null when the push record could not be read. */
  pushes: number | null
  deploys: number
}

/** One review that was applied to the course, from the commit history. */
export interface ReviewApplied {
  /** When it was committed. Format with `formatDate` or `formatDateTime`. */
  date: IsoDateTime
  /** The commit's subject line. */
  subject: string
}

// ══ Shared ═══════════════════════════════════════════════════════════════════

/**
 * A date and time as an ISO string: 'YYYY-MM-DDTHH:mm:ss' (mock data, no zone), or from the snapshot
 * with an offset ('…-06:00') or in UTC ('…Z'). The formatters in ./format take all three.
 */
export type IsoDateTime = string

/** A run of days, both ends included. */
export interface Period {
  /** First day, 'YYYY-MM-DD'. */
  start: IsoDate
  /** Last day, 'YYYY-MM-DD'. */
  end: IsoDate
}

/** The fixed date boundaries every "this week" / "this month" number is computed from. */
export interface Periods {
  /** Today, 2026-11-17. */
  today: IsoDate
  /** The last 7 days, 2026-11-11 to 2026-11-17. */
  thisWeek: Period
  /** The month to date, 2026-11-01 to 2026-11-17. */
  thisMonth: Period
  /** 2026-11-04 to 2026-11-17. */
  last14Days: Period
  /** 2026-10-19 to 2026-11-17: the cost-per-day chart. */
  last30Days: Period
}

/**
 * One stat card. Each page exports four, in page order: `contentStatTiles`, `healthStatTiles`,
 * `activityStatTiles` (real) and `growthStatCards`, `costStatCards` (mock).
 */
export interface StatTile {
  /** Stable key, e.g. 'lessons'. Use it as the React key. */
  id: string
  /** Card title, e.g. "Lessons". */
  label: string
  /**
   * The value, already formatted for display, e.g. "726", "87.8%", "259/259". When `measured` is
   * false this is the `NOT_MEASURED` label ("Not measured yet"), never a number.
   */
  value: string
  /** A short line under the title, e.g. "Last 7 days". */
  description: string
  /** false when the snapshot has no real source for this number. Mock cards: always true. */
  measured: boolean
  /**
   * The value at each snapshot, oldest first. null until the history holds two snapshots, for cards
   * with no matching history field, and for mock cards. Show the number alone when it is null.
   */
  trend: TrendPoint[] | null
}

/** One line or bar series of a chart: `id` is the key into each chart row, `name` is the legend text. */
export interface ChartSeries {
  id: string
  name: string
}

// ══ Growth (mock) ════════════════════════════════════════════════════════════

/** The six mock language ids of the Growth page. */
export type LanguageId = 'french' | 'spanish' | 'italian' | 'german' | 'portuguese' | 'dutch'

/**
 * One week of the lessons line chart: the cumulative number of lessons in each language at the end of
 * that week. Keyed by language id, so it is ready for a multi-line chart.
 */
export type LessonsWeek = { /** Week-ending day, 'YYYY-MM-DD'. */ date: IsoDate } & Record<LanguageId, number>

/** One row of the Growth table (one per mock language). */
export interface GrowthRow {
  /** Language id, e.g. 'french'. */
  id: LanguageId
  /** Display name, e.g. "French". */
  name: string
  /** Lessons added in the latest week: the last weekly point minus the one before. */
  addedThisWeek: number
  /** Lessons added this month: the last weekly point minus the latest point before the month began. */
  addedThisMonth: number
  /** Total lessons now: the last weekly point. */
  totalLessons: number
}

// ══ Agents (mock; for the Cost page) ══════════════════════════════════════════

export type AgentId = 'builder-1' | 'builder-2' | 'fable' | 'debugger'

export interface Agent {
  id: AgentId
  /** Display name: "Builder 1", "Builder 2", "Fable", "Debugger". */
  name: string
}

/** What one agent did on one day. There is a record for every agent on every day, zeros included. */
export interface AgentDay {
  date: IsoDate
  agentId: AgentId
  /** Runs started that day. */
  runs: number
  /** Tokens used that day. Format with `formatTokens`. */
  tokens: number
  /** Cost that day in US dollars, to the cent. Format with `formatCurrency`. */
  cost: number
}

/** Totals over any set of `AgentDay` records. */
export interface AgentTotals {
  runs: number
  tokens: number
  /** US dollars, to the cent. */
  cost: number
}

// ══ Cost (mock) ══════════════════════════════════════════════════════════════

/** One day of the cost-per-day bar chart. */
export interface CostByDayPoint {
  date: IsoDate
  /** Total cost of all agents that day in US dollars, to the cent. */
  cost: number
}

/** One row of the Cost table (one per agent, this month). */
export interface AgentCostRow extends AgentTotals {
  id: AgentId
  /** Display name, e.g. "Builder 1". */
  name: string
  /** cost / runs in US dollars, to the cent; 0 when there were no runs. */
  averageCostPerRun: number
}
